{
  "findings": [
    {
      "ref": "[D537]",
      "area": "age_gating",
      "claim": "The ESRB rating system includes age-based categories such as EC, E, E10+, T, M, and AO, and Brazil uses DEJUS ratings with similar age limits.",
      "stance": "neutral",
      "quote": "TITLES RATED EC (Early Childhood) have content that may be suitable for persons ages 3 and older. Titles in this category contain no material that parents would find inappropriate."
    },
    {
      "ref": "[D537]",
      "area": "content",
      "claim": "A parent reports that games rated EC contain no material that parents would find inappropriate.",
      "stance": "neutral",
      "quote": "TITLES RATED EC (Early Childhood) have content that may be suitable for persons ages 3 and older. Titles in this category contain no material that parents would find inappropriate."
    },
    {
      "ref": "[D537]",
      "area": "content",
      "claim": "A parent reports that games rated E may contain minimal cartoon, fantasy or mild violence and/or infrequent use of mild language.",
      "stance": "neutral",
      "quote": "TITLES RATED E (Everyone) have content that may be suitable for persons ages 6 and older. Titles in this category may contain minimal cartoon, fantasy or mild violence and/or infrequent use of mild language."
    },
    {
      "ref": "[D537]",
      "area": "content",
      "claim": "A parent reports that games rated T may contain violence, suggestive themes, crude humor, minimal blood and/or infrequent use of strong language.",
      "stance": "neutral",
      "quote": "TITLES RATED T (Teen) have content that may be suitable for persons ages 13 and older. Titles in this category may contain violence, suggestive themes, crude humor, minimal blood and/or infrequent use of strong language."
    },
    {
      "ref": "[D537]",
      "area": "content",
      "claim": "A parent reports that games rated M may contain violence, blood and gore, sexual content, and/or strong language.",
      "stance": "neutral",
      "quote": "TITLES RATED M (Mature) have content that may be suitable for persons 17 years and older. Titles in this category may contain violence, blood and gore, sexual content, and/or strong language."
    },
    {
      "ref": "[D537]",
      "area": "content",
      "claim": "A parent reports that Brazil's DEJUS rating 'Not recommended for viewers younger than 10 years of age' may contain a small amount of inappropriate language, sexual innuendo or mild violence.",
      "stance": "neutral",
      "quote": "(Especially recommended for Children and Adolescents): This content is recommended for children and adolescents. Contains educational materials and does not have any inappropriate content."
    },
    {
      "ref": "[D537]",
      "area": "content",
      "claim": "A parent reports that Brazil's DEJUS rating 'Not recommended for viewers younger than 12 years of age' may contain mild inappropriate language, mild sexual innuendo or mild violence.",
      "stance": "neutral",
      "quote": "(Not recommended for viewers younger than 12 years of age.) This content is recommended for persons who are at least 12 years of age. May contain mild inappropriate language, mild sexual innuendo or mild violence."
    },
    {
      "ref": "[D537]",
      "area": "content",
      "claim": "A parent reports that Brazil's DEJUS rating 'Not recommended for viewers younger than 14 years of age' may contain moderate inappropriate language, moderate sexual innuendo, mild sexual content or brief allusions to drug use.",
      "stance": "neutral",
      "quote": "(Not recommended for viewers younger than 14 years of age.) This content is recommended for persons who are at least 14 years of age. May contain moderate inappropriate language, moderate sexual innuendo, mild sexual content or brief allusions to drug use."
    },
    {
      "ref": "[D537]",
      "area": "content",
      "claim": "A parent reports that Brazil's DEJUS rating 'Not recommended for viewers younger than 16 years of age' may contain strong language, sexual innuendo or mild sex with or without mild nudity, strong violence or moderate scenes of or allusions to drug use.",
      "stance": "neutral",
      "quote": "(Not recommended for viewers younger than 16 years of age.) This content is recommended for persons who are at least 16 years of age. May contain strong language, sexual innuendo or mild sex with our without mild nudity, strong violence or moderate scenes of or allusions to drug use."
    },
    {
      "ref": "[D537]",
      "area": "content",
      "claim": "A parent reports that Brazil's DEJUS rating 'Not recommended for viewers younger than 18 years of age' is forbidden for people under 18 and may contain strong language, explicit sexual content, frequent nudity, strong violence or explicit scenes of drug abuse.",
      "stance": "neutral",
      "quote": "(Not recommended for viewers younger than 18 years of age.) This content is forbidden for people under 18 years of age. It may contain strong language, explicit sexual content, frequent nudity, strong violence or explicit scenes of drug abuse. This rating is also used for pornographic content."
    },
    {
      "ref": "[D537]",
      "area": "contact",
      "claim": "A parent reports that the PS4 system allows restricting communication with other players through parental controls.",
      "stance": "mitigation",
      "quote": "Communicating with Other Players\nUse this setting to restrict PlayStation Network communication features."
    },
    {
      "ref": "[D537]",
      "area": "money",
      "claim": "A parent reports that the PS4 system includes a monthly spending limit setting for each child in PlayStation Store.",
      "stance": "mitigation",
      "quote": "Monthly Spending Limit\nSet the maximum amount of money that each child can spend per month in PlayStation™Store."
    },
    {
      "ref": "[D537]",
      "area": "data",
      "claim": "A parent reports that the PS4 system offers a web filter to block dangerous or harmful sites when using the Internet Browser.",
      "stance": "mitigation",
      "quote": "Web Filter\nMake use of a web filtering service that verifies the type and safety of sites when the Internet Browser is being used, and automatically prevents dangerous or harmful sites from being displayed."
    },
    {
      "ref": "[D537]",
      "area": "developer_record",
      "claim": "A parent reports that Sony Interactive Entertainment provides product descriptions and ratings as a matter of convenience and encourages parental review, but there is no mention of fines, breaches, lawsuits or regulatory actions against the developer.",
      "stance": "neutral",
      "quote": "Legal\nAbout Ratings and Parental Controls (US)\nSony Interactive Entertainment provides product descriptions and ratings information as a matter of convenience for all users and not as a substitute for parental oversight. Parents are encouraged to review each piece of content prior to purchase or viewing."
    }
  ]
}
